import csv, math
files=['processed/forces.csv','processed/forces_b3.csv']
log={int(r['run_id']):r for r in csv.DictReader(open('data/run_log.csv'))}
groups={}
for fn in files:
 for r in csv.DictReader(open(fn)):
  rid=int(r['run']); m=log[rid]; U=float(m['speed_m_s']); D=float(m['diameter_mm'])/1000; F=float(r['F_mean'])
  Re=U*D/1.004e-6; Cd=F/(.5*998*U*U*D*.6)
  groups.setdefault(m['cylinder'],[]).append((rid,U,F,Cd,Re))
for k,v in groups.items():
 vals=[x[3] for x in v]; mu=sum(vals)/len(vals); sd=(sum((x-mu)**2 for x in vals)/(len(vals)-1))**.5
 print(k,'n',len(v),'mean',mu,'sd',sd,'range',min(vals),max(vals),'Re',min(x[4] for x in v),max(x[4] for x in v))
 for x in v: print(x)

